(function(){'use strict';function init(){document.querySelectorAll('.bmd-crmtco').forEach(function(root){var defs={users:3,seat:79,base:149,integrations:99,messages:0,setup:800,margin:300};var brl=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'});function val(k){var e=root.querySelector('[data-crm="'+k+'"]');if(!e)return 0;var n=Number(e.value);return Number.isFinite(n)?Math.max(0,n):0;}function write(k,v){var e=root.querySelector('[data-crm-out="'+k+'"]');if(e)e.textContent=v;}function update(){var users=Math.max(1,Math.floor(val('users'))),monthly=(users*val('seat'))+val('base')+val('integrations')+val('messages'),annual=monthly*12+val('setup'),margin=val('margin');write('monthly',brl.format(monthly));write('annual',brl.format(annual));write('effective',brl.format(annual/12));write('break-even',margin>0?'Para cobrir esse custo anual, seriam necessários pelo menos '+Math.ceil(annual/margin).toLocaleString('pt-BR')+' clientes adicionais com margem de '+brl.format(margin)+' por cliente.':'Informe a margem por cliente para estimar o ponto de equilíbrio.');}root.querySelectorAll('input[data-crm]').forEach(function(e){e.addEventListener('input',update)});var btn=root.querySelector('.bmd-crmtco-reset');if(btn)btn.addEventListener('click',function(){Object.keys(defs).forEach(function(k){var e=root.querySelector('[data-crm="'+k+'"]');if(e)e.value=defs[k]});update();});update();})}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();